(function(){'use strict';var PREVIEW_STEPS=2;var RESUME_KEY='rsc-lesson-v1:'+location.pathname;function ready(fn){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',fn);else fn();}
ready(function(){var content=document.getElementById('content')||document.body;var steps=Array.prototype.slice.call(content.querySelectorAll('.lesson-step'));if(!steps.length)return;var body=document.body;var ds=body.dataset||{};var access=(body.getAttribute('data-lesson-access')||'free').toLowerCase();var courseTitle=ds.courseTitle||'Course';var landing=ds.courseLanding||'/';var nextHref=ds.courseNext||'';var total=steps.length;var state={furthest:0,passed:{}};try{var saved=JSON.parse(localStorage.getItem(RESUME_KEY));if(saved&&typeof saved==='object'){state.furthest=saved.furthest||0;state.passed=saved.passed||{};}}catch(e){}
function save(){try{localStorage.setItem(RESUME_KEY,JSON.stringify(state));}catch(e){}}
var app=document.createElement('div');app.className='lm-app';app.innerHTML='<div class="lm-top">'+'<a class="lm-exit" href="'+esc(landing)+'">'+'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>'+
esc(courseTitle)+'</a>'+'<span class="lm-title">'+esc(courseTitle)+
(ds.courseLesson&&ds.courseTotal?' <span>&middot; Lesson '+esc(ds.courseLesson)+' of '+esc(ds.courseTotal)+'</span>':'')+'</span>'+'<div class="lm-top-right">'+'<span class="lm-stepn">Step <b class="lm-cur">1</b> / '+total+'</span>'+'<a class="lm-cert" href="/pricing.html">Get certified</a>'+'</div>'+'</div>'+'<div class="lm-segs">'+steps.map(function(){return'<i></i>';}).join('')+'</div>'+'<div class="lm-stage"></div>'+'<div class="lm-stepper">'+'<button class="lm-back" disabled>&larr; Back</button>'+'<span class="lm-mid"></span>'+'<button class="lm-cont">Continue &rarr;</button>'+'</div>';var stage=app.querySelector('.lm-stage');steps.forEach(function(s){stage.appendChild(s);});body.appendChild(app);body.classList.add('lesson-js-ready');var segEls=Array.prototype.slice.call(app.querySelectorAll('.lm-segs i'));var curEl=app.querySelector('.lm-cur');var midEl=app.querySelector('.lm-mid');var backBtn=app.querySelector('.lm-back');var contBtn=app.querySelector('.lm-cont');var locked=(access==='pro')&&!body.classList.contains('pro');document.addEventListener('auth-hydrated',function(e){var pro=!!(e.detail&&e.detail.me&&e.detail.me.pro);if(pro&&locked){locked=false;render();}
hydrateSolved();});var API=window.RSCExerciseAPI;var hub=API?API.hubSlugFromPath():'';function exerciseId(step){var ex=step.querySelector('.exercise');return ex?ex.getAttribute('data-exercise-id'):'';}
function markPassed(idx){if(state.passed[idx])return;state.passed[idx]=true;save();var id=exerciseId(steps[idx]);if(API&&id)API.reportSolve(hub,id,0);}
function hydrateSolved(){if(!API)return;API.fetchSolved(hub).then(function(ids){if(!ids||!ids.length)return;steps.forEach(function(step,idx){var id=exerciseId(step);if(id&&ids.indexOf(id)!==-1&&!state.passed[idx]){state.passed[idx]=true;step.classList.add('passed');}});save();render();});}
app.querySelectorAll('.lesson-quiz').forEach(function(quiz){var step=quiz.closest('.lesson-step');var idx=steps.indexOf(step);var correct=parseInt(quiz.getAttribute('data-correct'),10);var opts=Array.prototype.slice.call(quiz.querySelectorAll('.lesson-opt'));if(state.passed[idx])step.classList.add('passed');opts.forEach(function(opt){opt.addEventListener('click',function(){if(quiz.classList.contains('answered'))return;quiz.classList.add('answered');var chosen=parseInt(opt.getAttribute('data-i'),10);var right=chosen===correct;opts.forEach(function(o,j){o.classList.add('dim');if((j+1)===correct)o.classList.remove('dim');});opt.classList.remove('dim');opt.classList.add(right?'correct':'wrong');if(!right)opts[correct-1].classList.add('correct');var fb=quiz.querySelector('.lesson-qfb-'+(right?'ok':'no'));if(fb)fb.classList.add('show');step.classList.add('passed');markPassed(idx);render();});});});app.querySelectorAll('.lesson-tryit').forEach(function(tryit){var step=tryit.closest('.lesson-step');var idx=steps.indexOf(step);if(state.passed[idx])step.classList.add('passed');var input=tryit.querySelector('.lesson-tryit-input');var checkBtn=tryit.querySelector('.lesson-tryit-check');var ok=tryit.querySelector('.lesson-tryit-ok');var no=tryit.querySelector('.lesson-tryit-no');var re=null;try{re=new RegExp(tryit.getAttribute('data-check-regex'));}catch(e){}
if(checkBtn)checkBtn.addEventListener('click',function(){var pass=re?re.test(input.value):true;if(ok)ok.classList.toggle('show',pass);if(no)no.classList.toggle('show',!pass);if(pass){step.classList.add('passed');markPassed(idx);render();}});});var i=Math.min(state.furthest||0,total-1);var showingPaywall=false;function gated(idx){return steps[idx].hasAttribute('data-gate')&&!steps[idx].classList.contains('passed');}
function renderPaywall(){showingPaywall=true;steps.forEach(function(s){s.classList.remove('on');});var pw=stage.querySelector('.lm-paywall');if(!pw){pw=document.createElement('div');pw.className='lm-paywall';pw.innerHTML='<h3>Continue this course with Pro</h3>'+'<p>The first lessons are free. Unlock the full '+esc(courseTitle)+' course, every interactive lesson, and your certificate with Pro.</p>'+'<a href="/pricing.html">See plans &rarr;</a>';stage.appendChild(pw);}
pw.style.display='';curEl.textContent=Math.min(i+1,total);midEl.textContent='Preview complete';backBtn.disabled=false;contBtn.disabled=true;stage.scrollTop=0;}
function render(){if(showingPaywall){var p=stage.querySelector('.lm-paywall');if(p)p.style.display='none';showingPaywall=false;}
steps.forEach(function(s,k){s.classList.toggle('on',k===i);});segEls.forEach(function(e,k){e.className=k<i?'done':(k===i?'cur':'');});curEl.textContent=i+1;midEl.textContent='Step '+(i+1)+' of '+total;backBtn.disabled=i===0;var last=i===total-1;contBtn.innerHTML=last?(nextHref?'Next lesson &rarr;':'Finish &check;'):'Continue &rarr;';contBtn.disabled=gated(i);if(i>state.furthest){state.furthest=i;save();}
if(window.LessonWidgets)window.LessonWidgets.mountAll(steps[i]);stage.scrollTop=0;}
function go(delta){var target=i+delta;if(target<0||target>=total){if(target>=total&&i===total-1&&nextHref){location.href=nextHref;}
return;}
if(delta>0&&locked&&target>=PREVIEW_STEPS){renderPaywall();return;}
i=target;render();}
backBtn.addEventListener('click',function(){if(showingPaywall){render();return;}
go(-1);});contBtn.addEventListener('click',function(){go(1);});document.addEventListener('keydown',function(e){if(e.key==='ArrowRight'&&!contBtn.disabled)go(1);else if(e.key==='ArrowLeft'&&!backBtn.disabled)go(-1);});if(locked&&i>=PREVIEW_STEPS)i=PREVIEW_STEPS-1;render();if(API&&API.token&&API.token())hydrateSolved();});function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c];});}})();